script:
frappe.ui.form.on('Healthcare Practitioner', {
    refresh(frm) {
        // Run on load
        toggle_salutation_editable(frm);
        frm.set_df_property('practitioner_name', 'read_only', 1); // practitioner_name read-only
        update_practitioner_name(frm);
    },
    employee(frm) {
        // Run whenever employee changes
        toggle_salutation_editable(frm);
        update_practitioner_name(frm);
    },
    custom_salutation(frm) {
        update_practitioner_name(frm);
    },
    first_name(frm) {
        update_practitioner_name(frm);
    },
    middle_name(frm) {
        update_practitioner_name(frm);
    },
    last_name(frm) {
        update_practitioner_name(frm);
    }
});

function toggle_salutation_editable(frm) {
    if (frm.doc.employee) {
        // If employee selected, keep salutation fetched + read-only
        frm.set_df_property('custom_salutation', 'read_only', 1);
    } else {
        // If employee empty, make salutation editable
        frm.set_df_property('custom_salutation', 'read_only', 0);
    }
    frm.refresh_field('custom_salutation');
}

function update_practitioner_name(frm) {
    let parts = [];
    if (frm.doc.custom_salutation) parts.push(frm.doc.custom_salutation);
    if (frm.doc.first_name) parts.push(frm.doc.first_name);
    if (frm.doc.middle_name) parts.push(frm.doc.middle_name);
    if (frm.doc.last_name) parts.push(frm.doc.last_name);
    let practitioner_name = parts.join(' ').trim();
    
    // Update practitioner_name in frm.doc without triggering dirty state
    if (frm.doc.practitioner_name !== practitioner_name) {
        frm.doc.practitioner_name = practitioner_name;
        frm.refresh_field('practitioner_name');
    }
}
